INSERT INTO capsules (id, name, spirit, img_box, img_pour, description, sort_order) VALUES
  ('caramel-appletini', 'Caramel Appletini', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/caramel-appletini-from-bartesian_1.png?v=1753126776', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/CA_bbf02308-9bd7-499a-862f-b5e0633ac3cf.jpg?v=1753126776', 'The Caramel Appletini is a wickedly smooth cocktail that blends flavors of tart green apple with rich, velvety caramel for a spellbinding sip.', 1),
  ('witchs-heart-cocktails', 'Witch''s Heart', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/witchs-heart-from-bartesian_1.png?v=1753128387', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/2_Witch_sHeart_2022.png?v=1753128387', 'The perfect Halloween cocktail, Witch''s Heart is a blend of berry and green apple flavors to help you get in the spirit of the season.', 2),
  ('sour-spell-capsules', 'Sour Spell', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/sour-spell-capsule-from-bartesian.png?v=1785248829', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/SourSpellTopView-FullUsage.jpg?v=1787938085', 'Sour Spell is a sweet vodka cocktail with a mischievous glow and a burst of sour rainbow candy flavor.', 3),
  ('vampires-kiss-capsules', 'Vampire''s Kiss', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/vampires-kiss-capsule-from-bartesian.png?v=1785248821', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Vampire_sKisswithProfessional-FullUsage.jpg?v=1787938287', 'Vampire''s Kiss is a deep crimson vodka cocktail built around the unmistakable sweetness of red licorice flavor, layered with juicy strawberry and fruit punch flavor.', 4),
  ('golden-ace-capsules', 'Golden Ace', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/golden-ace-from-bartesian.png?v=1753897405', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Honey.Deuce.Square.jpg?v=1753897405', 'This grand slam of a vodka cocktail refreshingly blends the flavors of tart lemonade, fruity raspberry liqueur, and sweet honeydew melon.', 5),
  ('rum-swizzle-capsules', 'Rum Swizzle', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/rum-swizzle-capsule-from-bartesian.png?v=1722438425', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/rum.swizzle.wht.jpg?v=1722438460', 'Known as Bermuda’s national drink, the Rum Swizzle is a fresh and fruity cocktail enjoyed around the world.', 6),
  ('mango-habanero-margarita-capsules', 'Mango Habanero Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/mango-habanero-margarita_2.png?v=1780330135', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Mango.Habanero.Margarita.WHT_use.jpg?v=1779891782', 'Tropical and fiery, this vibrant margarita pairs ripe mango and lime juices with a kick of habanero flavor. Each sip unfolds with the perfect harmony of sweet and heat.', 7),
  ('watermelon-margarita-capsules', 'Watermelon Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/watermelon-margarita-frombartesian_0d8db9de-e450-4524-bfeb-98a72a5519af.png?v=1779892563', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Watermelon.Margarita.wht.jpg?v=1717436942', 'Like summertime in a glass, the Watermelon Margarita is a refreshing sweet and salty tequila cocktail blending watermelon, citrus, and triple sec flavors.', 8),
  ('calamansi-daiquiri-capsules', 'Calamansi Daiquiri', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/calamansi-daidquiri-capsule-from-bartesian-wsl.png?v=1766173481', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Calamansi.Daiquiri.WHT_1_2_bb331d49-c06a-451b-a65f-9faf93cc617b.jpg?v=1766173481', 'Calamansi - bright, exotic, and irresistibly tart - transforms the classic daiquiri into something unforgettable.', 9),
  ('blackberry-mango-capsules', 'Blackberry Mango Refresher', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/blackberry-mango-refresher-capsule-from-bartesian_1.png?v=1769199883', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Blackberry_Mango_Refresher_Solo_with_Splash_-_Full_Usage.jpg?v=1769200108', 'Some days call for a little extra lift - and this lightly caffeinated Refresher delivers.', 10),
  ('peach-lychee-capsules', 'Peach Lychee Refresher', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/peach-lychee-refresher-capsule-from-bartesian.png?v=1769199802', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Peach_Lychee_Refresher_Solo_with_Splash_-_Full_Usage.jpg?v=1769200168', 'With juicy peach and delicate lychee flavors, this lightly caffeinated Refresher is a gentle nudge in the right direction.', 11),
  ('strawberry-acai-capsules', 'Strawberry Acai Refresher', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/strawberry-acai-refresher-capsule-from-bartesian.png?v=1769199842', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Strawberry-Acai-Refresher-Solo-with-Splash---Full-Usage.jpg?v=1769199969', 'When you need refreshment, look no further. Flavors of lush strawberry and tangy acai blend in a perfect balance of sweet and tart.', 12),
  ('strawberry-coconut-daiquiri-capsules', 'Strawberry Coconut Daiquiri', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/strawberry-coconut-diaquiri-from-bartesian.png?v=1711654651', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Strawberry.coconut.jpg?v=1719260412', 'The Strawberry Coconut Daiquiri is the perfect poolside rum cocktail with flavors of juicy strawberry, sweet coconut, and tart lime.', 13),
  ('lychee-martini-capsules', 'Lychee Martini', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/lychee-martini-capsule-from-bartesian.png?v=1708111164', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/lychee.martini.jpg?v=1709072904', 'Delicately fruity and lightly floral, the Lychee Martini is an elegant, slightly sweeter twist on a vodka martini.', 14),
  ('low-cal-old-fashioned-capsules', 'Low-Cal Old Fashioned', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/low-cal-old-fashioned-from-bartesian.png?v=1758206929', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/OldFashioned_6d6c1834-d737-40bd-840a-47c00b5ed973.png?v=1758206929', 'The Low-Cal Old Fashioned is a spirit-forward whiskey cocktail that perfectly balances bitter and sweet, with notes of oak and orange citrus.', 15),
  ('strawberry-guava-margarita-capsules', 'Strawberry Guava Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/strawberry_guava_margarita.png?v=1692809162', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Strawb.Guava.Margarita.wht.jpg?v=1692809162', 'Sweet and refreshing, the Strawberry Guava Margarita is a fruit-forward cocktail with tropical guava combined with flavors of strawberry, triple sec, and lime.', 16),
  ('white-sangria-capsules', 'White Sangria', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/white-sangria-capsule-from-bartesian.png?v=1722268502', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/White_Sangria_ALT.png?v=1722268531', 'Sangria is a lively, wine-based punch traditionally sweetened with fruit and fortified with additional liquor or liqueurs.', 17),
  ('tequila-sunrise-capsules', 'Tequila Sunrise', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/tequila-sunrise-capsule-from-bartesian.png?v=1722268485', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/Tequila.Sunrise.jpg?v=1722268503', 'This classic brunch tequila cocktail mixes orange juice with sweet grenadine cherry notes. Serve over ice in a lowball garnished with an orange wedge and maraschino cherry.', 18),
  ('painkiller-capsules', 'Painkiller', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/painkiller-capsule-from-bartesian.png?v=1722438410', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/painkiller.jpg?v=1722438444', 'Embrace the vacation mindset and put your troubles behind you.', 19),
  ('pomegranate-margarita-cocktails', 'Pomegranate Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/pomegranate-margarita-capsule-from-bartesian.png?v=1722268360', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/POM_MARG_PDP_2.jpg?v=1722268391', 'A tart, refreshing addition to the collection of Bartesian Margaritas , the pomegranate margarita is a perfect pick for any tequila lover.', 20),
  ('espresso-martini-capsules', 'Espresso Martini', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/espresso-martini-capsule-from-bartesian.png?v=1722268122', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/ESPRESSOMARTINI_WEB_2.png?v=1722268132', 'A crowd-pleaser for even the most refined palates, the Espresso Martini is a smooth, sippable cocktail with notes of rich and creamy espresso and bold coffee liqueur.', 21),
  ('jungle-bird-capsules', 'Jungle Bird', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/jungle-bird-capsule-from-bartesian.png?v=1722438255', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/JB_Solo.png?v=1722438283', 'Take a tropical adventure to the jungle! The Jungle Bird is a unique tiki rum cocktail driven by pineapple juice balanced with refreshing lime and bitters.', 22),
  ('raspberry-ginger-gimlet-capsules', 'Raspberry Ginger Gimlet', 'gin', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/raspberry-ginger-gimlet-capsule-from-bartesian.png?v=1722268365', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/RaspberryGingerGimlet_0.png?v=1722268399', 'The classic lime and gin cocktail gets a twist with flavors of sweet raspberry and a tangy ginger zing. Shake with ice and serve in a coupe glass.', 23),
  ('pineapple-margarita-capsules', 'Pineapple Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/pineapple-margarita-capsule-from-bartesian.png?v=1722268357', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/PineappleMarg2.png?v=1722268386', 'With summer on the horizon, there''s no better cocktail than our new Pineapple Margarita, bursting with notes of juicy tart pineapple and sweet coconut, balanced with lime and notes of orange triple sec.', 24),
  ('sidecar-capsules', 'Sidecar', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/sidecar-capsule-from-bartesian.png?v=1722438430', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Sidecar.jpg?v=1722438617', 'The Sidecar is a cocktail that transports you straight to the roaring ’20s: smoky jazz clubs, glittering chandeliers, and effortless style.', 25),
  ('bees-knees', 'Bee''s Knees', 'gin', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/bees-knees-capsule-from-bartesian.png?v=1722268086', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/bee_sknees.png?v=1722268088', 'A sweet, citrus, and refreshing cocktail from the Prohibition Era, the Bee''s Knees is a delicious pairing of lemon and honey, combined with floral notes of clover and alfalfa.', 26),
  ('hurricane', 'Hurricane', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/hurricane-capsule-from-bartesian.png?v=1722268172', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/1-1_Hurricane_e3697d47-ea3a-44b0-97d7-e79740e0b694.png?v=1722268196', 'Bring Mardi Gras home with the Hurricane. This sweet, fruity, and tropical rum cocktail derives tart and sour flavors from passion fruit and sweetness from orange juice.', 27),
  ('blackberry-margarita-cocktails', 'Blackberry Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/blackberry-margarita-capsule-from-bartesian.png?v=1722268098', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/1x1_Blackberry_Marg.png?v=1722268106', 'The Blackberry Margarita provides sweet and slightly tart berry notes with flavors of honeyed fig to create a juicy and jammy combination. Pairs perfectly with our Stemless Margarita glassware .', 28),
  ('apple-pie', 'Apple Pie', 'multi', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/apple-pie-capsule-from-bartesian.png?v=1722438106', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Apple.Pie.jpg?v=1722438669', 'Your favorite dessert is now served as a whiskey and vodka cocktail.', 29),
  ('passion-fruit-margarita-cocktails', 'Passion Fruit Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/passion-fruit-margarita-capsule-from-bartesian.png?v=1722268352', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/passionfruitmarg.png?v=1722268381', 'Embrace the aromatic flavors of Passion Fruit Margaritas at home whenever you please with the Bartesian cocktail maker and cocktail capsules.', 30),
  ('rum-runner-cocktails', 'Rum Runner', 'multi', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/rum-runner-capsule-from-bartesian.png?v=1722438419', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/RumRunner.png?v=1722438455', 'Whether you’re embarking on a Caribbean getaway or mixing up the popular rum cocktail for guests in your home, the Rum Runner Cocktail is a popular choice for its smooth flavors and vivid aesthe', 31),
  ('mango-margarita-cocktails', 'Mango Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/mango-margarita-capsule-from-bartesian.png?v=1722268243', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/mangomargarita.png?v=1722268257', 'This cocktail is a fruity, juicy, and refreshing margarita with a sweet blend of tequila, mango, and lime served over ice with a salted rim. Pairs perfectly with our Stemless Margarita glassware .', 32),
  ('low-calorie-margarita-cocktails', 'Low-Cal Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/low-cal-margarita-capsule-from-bartesian.png?v=1722438263', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/margarita.png?v=1722438392', 'The low calorie Margarita is a classic, refreshing blend of tequila, lemon, and lime for a sweet and sour citrus experience. A salted rim perfectly complements the citrus of the fruits.', 33),
  ('amaretto-sour-cocktails', 'Amaretto Sour', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/amaretto-sour-capsule-from-bartesian.png?v=1722268011', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/amaretto.png?v=1722268019', 'The Amaretto Sour pairs nutty almond and orange citrus notes to make for the perfect vodka dessert cocktail.', 34),
  ('whiskey-smash-cocktails', 'Whiskey Smash', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/whiskey-smash-capsule-from-bartesian.png?v=1722268495', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/Wiskey.smash.jpg?v=1722268519', 'There are no sure things in life, but when you combine a Whiskey Sour and a Mint Julep the resulting delicious Whiskey Smash is about as close as you can get.', 35),
  ('low-calorie-whiskey-sour-cocktails', 'Low-Cal Whiskey Sour', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/low-cal-whiskey-sour-capsule-from-bartesian.png?v=1722438403', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/lowcalwhiskeysour.png?v=1722438431', 'Ready for a guilt-free whiskey delight? Bartesian’s Low-Calorie Whiskey Sour capsules are here to shake up your cocktail game!', 36),
  ('aviation-cocktails', 'Aviation', 'gin', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/aviation-capsule-from-bartesian.png?v=1722438130', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/aviation.png?v=1722438134', 'Bright, floral and slightly sweet, this gin favorite brings together flavors of Crème de Violette, Maraschino liqueur, and a squeeze of lemon for a drink that’s as refreshing as it is eye-catching.', 37),
  ('vodka-martini-lemon-drop-cocktails', 'Lemon Drop', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/lemon-drop-capsule-from-bartesian.png?v=1722268183', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/lemondrop.png?v=1722268201', 'The Lemon Drop vodka martini is as tasty as its candy namesake but with the added bonus of vodka.', 38),
  ('jalapeno-lime-shrub-cocktails', 'Jalapeno Lime Shrub', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/jalapeno-lime-shrub-capsule-from-bartesian.png?v=1722438249', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/jalapenolimeshrub.png?v=1722438276', 'Bartesian''s Jalapeño Lime Shrub cocktail capsules create a cocktail that''s like a lively dance of flavors on your tongue!', 39),
  ('northside-cocktails', 'Northside', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/northside-capsule-from-bartesian.png?v=1722268346', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/Northside.png?v=1722268369', 'With Moscow Mule-inspired flavors, this smooth, sweet and tart lime vodka libation, the Northside is like a cool breeze on a hot day.', 40),
  ('low-calorie-cosmopolitan-martini-cocktails', 'Low-Cal Cosmopolitan', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/low-cal-cosmopolitan-capsule-from-bartesian.png?v=1722438259', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/lowcalcosmo.png?v=1722438290', 'Enjoy a guilt-free Cosmo with our low-calorie option! Tart cranberry is balanced out by the citrus of lime and the sweetness of orange to create this classic vodka cocktail.', 41),
  ('mai-tai-cocktails', 'Mai Tai', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/mai-tai-capsule-from-bartesian.png?v=1722268238', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/maitai.png?v=1722268250', 'A tropical classic with layers of bright lime, tart pineapple, and smooth almond flavor.', 42),
  ('ginger-peach-iced-tea-cocktails', 'Ginger Peach Iced Tea', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/ginger-peach-iced-tea-capsule-from-bartesian.png?v=1722268168', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/gingerpeachicedtea.png?v=1722268184', 'Bartesian’s Ginger Peach Iced Tea capsules offer a delightful blend of flavors that creates the perfect cocktail for those warm, sunny days.', 43),
  ('spicy-margarita-cocktails', 'Spicy Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/spicy-margarita-from-bartesian.png?v=1722442445', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/SpicyMarg.png?v=1722442447', 'Ready to spice things up? This margarita is for you. Savor the classic combination of lemon and lime with a fiery twist of jalapeño and cayenne flavor.', 44),
  ('manhattan-cocktails', 'Manhattan', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/manhattan-capsule-from-bartesian.png?v=1722268246', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/manhattan.png?v=1722268263', 'Named after New York City''s Manhattan Club, this timeless cocktail stirred up its popularity with its mix of strong whiskey, sweet vermouth, and aromatic bitters. Garnish with a cherry.', 45),
  ('whiskey-sour-cocktails', 'Whiskey Sour', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/whiskey-sour-capsule-from-bartesian.png?v=1722268498', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/WhiskeySour.png?v=1722268525', 'The Whiskey Sour provides a smooth balance of sweet and sour. Notes of vanilla, lemon, and orange round out the flavor profile and make for a classic whiskey citrus cocktail.', 46),
  ('paper-plane-cocktails', 'Paper Plane', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/paper-plane-capsule-from-bartesian.png?v=1722438415', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/paperplane.png?v=1722438449', 'The Paper Plane expertly blends bitter, herbal, and sour notes with elegant symmetry. The flavor profile of this whiskey cocktail is finished with a touch of lemon citrus and sweetness.', 47),
  ('long-island-iced-tea-cocktails', 'Long Island Iced Tea', 'multi', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/long-island-capsule-from-bartesian.png?v=1722268212', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/longislandicedtea.png?v=1722268214', '*', 48),
  ('old-fashioned-cocktails', 'Old Fashioned', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/old-fashioned-capsule-from-bartesian.png?v=1722268350', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/OldFashioned_40d51d3a-fed8-485d-9435-59326ecccb8c.png?v=1702652130', 'The Old Fashioned is a spirit-forward whiskey cocktail that perfectly balances bitter and sweet, with notes of oak and orange citrus.', 49),
  ('cosmopolitan-martini-cocktails', 'Cosmopolitan', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/cosmopolitan-capsule-from-bartesian.png?v=1722268117', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/cosmo.png?v=1722268141', 'Tart cranberry is balanced out by the citrus of lime and sweetness of orange to create this classic vodka cocktail.', 50),
  ('sex-on-the-beach-vodka-cocktails', 'Sex on the Beach', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/sex-on-the-beach-capsule-from-bartesian.png?v=1722268455', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/product-4.png?v=1722268465', 'The most iconic beach cocktail of all time is undoubtedly the Sex on the Beach.', 51),
  ('rum-breeze-cocktails', 'Rum Breeze', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/rum-breeze-capsule-from-bartesian.png?v=1722268369', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/product-3.png?v=1722268408', 'The Rum Breeze features a sweet, tropical blend of pineapple, lime, and strawberry juices, light rum, and a hint of coconut. Fresh and flavorful, it’s a must-have addition to your at-home bar.', 52),
  ('gin-cocktails-uptown-rocks', 'Uptown Rocks', 'gin', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/uptown-rocks-capsule-from-bartesian.png?v=1722268488', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/uptownrocks.png?v=1722268510', 'An elegant gin cocktail featuring peach and lemon with a graceful kick of cilantro flavor. Take gin drinks to the next level with an herbal gin for a smooth finish for this refreshing cocktail.', 53),
  ('margarita-cocktails', 'Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/margarita-capsule-from-bartesian.png?v=1722268251', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/products/product-1.png?v=1722268296', 'The Margarita is a classic, refreshing blend of tequila, lemon, and lime for a sweet and sour citrus experience. A salted rim perfectly complements the citrus of the fruits.', 54)
